gabarito_ou_materiais:
frase = input()
limpa = frase.replace(' ', '').lower()
if limpa == limpa[::-1]:
    print('Palindromo')
else:
    print('Nao palindromo')

n = int(input())
original = []
for _ in range(n):
    original.append(int(input()))
unicos = []
for x in original:
    if x not in unicos:
        unicos.append(x)
print(unicos)

frase = input()
limpa = frase.replace(' ', '').lower()
if limpa == limpa[::-1]:
    print('Palindromo')
else:
    print('Nao palindromo')

n = int(input())
div = 2
eh_primo = True
while div * div <= n:
    if n % div == 0:
        eh_primo = False
        break
    div += 1
if eh_primo:
    print('Primo')
else:
    print('Composto')

a = float(input())
b = float(input())
c = float(input())
if a < b + c and b < a + c and c < a + b:
    if a == b and b == c:
        print('Equilatero')
    elif a == b or a == c or b == c:
        print('Isosceles')
    else:
        print('Escaleno')
else:
    print('Nao forma triangulo')

